	autoReset: boolean;
	auth: {
		openai: boolean;
		commandcode: boolean;
		opencodeGo: boolean;
		grok: boolean;
		lithosai: boolean;
		openrouter: boolean;
		openrouterManagement: boolean;
		claude: boolean;
	};
};

