export function ticketUseParts(use: { at: number; result: string; source: string }): {
	verb: string;
	day: string;
	clock: string;
	source: string | null;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" }),
		source: use.result === "expired" ? null : use.source,
	};
}

/** One ticket history row: `Used Oct 23 00:55 · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string }): string {
	const { verb, day, clock, source } = ticketUseParts(use);
	return source ? `${verb} ${day} ${clock} · ${source}` : `${verb} ${day} ${clock}`;
}

edits.newText:
type TicketKind = { scope?: string; model?: string };

/** `Fable` for a model reset; `Full` when it clears every window, or the row predates the field. */
export function ticketKind(ticket: TicketKind): string {
	const model = ticket.scope === "model" ? ticket.model?.trim() : "";
	return model || "Full";
}

/** `Fable reset` / `Full reset`. A cache from before model resets reads as a full reset. */
export function ticketName(ticket: TicketKind): string {
	return `${ticketKind(ticket)} reset`;
}

/** What spending it clears: one model's allowance, or weekly usage now. */
export function ticketEffect(ticket: TicketKind): string {
	const model = ticket.scope === "model" ? ticket.model?.trim() : "";
	if (model) return `Resets the ${model} allowance`;
	return "Clears weekly usage now";
}

/** Still-spendable tickets, soonest expiry first. A lapsed one is dropped. */
export function liveTickets<T extends { expiresAt: number }>(tickets: readonly T[], now = Date.now()): T[] {
	return tickets
		.filter((ticket) => {
			const ms = resetAtMs(ticket.expiresAt);
			return ms != null && ms > now;
		})
		.sort((a, b) => (resetAtMs(a.expiresAt) ?? 0) - (resetAtMs(b.expiresAt) ?? 0));
}

/** The soonest live ticket that clears weekly usage. A model reset never drives that chart. */
export function weeklyTicket<T extends { expiresAt: number; scope?: string }>(
	tickets: readonly T[],
	now = Date.now(),
): T | undefined {
	return liveTickets(tickets, now).find((ticket) => ticket.scope !== "model");
}

/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, kind, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: { at: number; result: string; source: string } & TicketKind): {
	verb: string;
	day: string;
	clock: string;
	source: string | null;
	kind: string;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" }),
		source: use.result === "expired" ? null : use.source,
		kind: ticketKind(use),
	};
}

/** One ticket history row: `Used Oct 23 00:55 · Full reset · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string } & TicketKind): string {
	const { verb, day, clock, source } = ticketUseParts(use);
	const name = ticketName(use);
	return source ? `${verb} ${day} ${clock} · ${name} · ${source}` : `${verb} ${day} ${clock} · ${name}`;
}

