export function clampUsedPercent(usedPercent: number): number {
	if (!Number.isFinite(usedPercent)) return 0;
	return Math.max(0, Math.min(100, Math.round(usedPercent)));
}

/** Cents -> `$3.80`. Prepaid spend is a dollar figure, never a percentage. */
export function formatUsd(cents: number): string {
	if (!Number.isFinite(cents)) return "$0.00";
	return `$${(cents / 100).toFixed(2)}`;
}

export function resetAtMs(resetAt?: number): number | null {
	if (resetAt == null || !Number.isFinite(resetAt)) return null;
	return resetAt > 1e12 ? resetAt : resetAt * 1000;
}

/** Compact remaining duration: "47m", "3h 54m", "6d 7h". */
export function formatResetDuration(ms: number): string {
	if (ms <= 0) return "now";
	const totalMins = Math.floor(ms / 60_000);
	if (totalMins < 60) return `${totalMins}m`;
	const hours = Math.floor(totalMins / 60);
	const mins = totalMins % 60;
	if (hours >= 24) {
		const days = Math.floor(hours / 24);
		const remHours = hours % 24;
		return remHours > 0 ? `${days}d ${remHours}h` : `${days}d`;
